import java.util.*;
public class TopologicalSort {
    public List<Integer> topoSort(int v, List<List<Integer>> adj) {
        int[] inDeg = new int[v];
        for (List<Integer> nbrs : adj)
            for (int nb : nbrs) inDeg[nb]++;
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < v; i++) if (inDeg[i] == 0) q.offer(i);
        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int node = q.poll();
            order.add(node);
            for (int nb : adj.get(node)) if (--inDeg[nb] == 0) q.offer(nb);
        }
        if (order.size() != v) System.out.println("Cycle detected!");
        return order;
    }
}

