vector<int> topoSort(int V, vector<vector<int>>& adj){
    vector<int> in(V,0);
    for(auto& nbrs:adj) for(int nb:nbrs) in[nb]++;
    queue<int> q; for(int i=0;i<V;i++) if(!in[i]) q.push(i);
    vector<int> res;
    while(!q.empty()){int u=q.front();q.pop();res.push_back(u);for(int nb:adj[u]) if(--in[nb]==0) q.push(nb);}
    return res;
}

