from collections import deque

def topological_sort(n, graph):
    indegree = [0] * n
    for u in graph:
        for v in graph[u]:
            indegree[v] += 1
    queue = deque(u for u in range(n) if indegree[u] == 0)
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    return order if len(order) == n else None  # None = cycle

graph = {5: [2, 0], 4: [0, 1], 2: [3], 3: [1]}
